function parse(value, fallback) { try { return typeof value === 'string' ? JSON.parse(value) : (value || fallback); } catch (_) { return fallback; } }
function records(value) { const body = parse(value?.body ?? value ?? {}, {}); return Array.isArray(body?.records) ? body.records : []; }
const context = $("Postgres Load Ticket For Manager").all()[0]?.json || {};
const ticket = parse(context.ticket, {}); const cfg = parse(context.airtable, {}); const contacts = parse(context.contacts, {});
let rows = []; try { rows = records($input.all()[0]?.json); } catch (_) {}
const trade = String(ticket.trade || '').toUpperCase(); const propertyMatch = String(ticket.body_raw || '').match(/(?:^|\\n)Property:\\s*([^\\n]+)/i); const property = [ticket.unit_match_display, ticket.unit_identifier, propertyMatch?.[1]].filter(Boolean).join(' ').toUpperCase();
const candidates = rows.map(r => ({id:r.id, name:r.fields?.['Vendor Name'] || '', email:r.fields?.Email || '', active:String(r.fields?.Active || '').toLowerCase() !== 'no', trades:String(r.fields?.Trades || '').toUpperCase(), properties:String(r.fields?.Properties || '').toUpperCase(), priority:Number(r.fields?.Priority || 999)}))
  .filter(v => v.active && v.name && v.email && v.trades.includes(trade) && (!v.properties || property.includes(v.properties) || v.properties.includes(property.split(' - ')[0] || '')))
  .sort((a,b) => a.priority - b.priority).slice(0,3);
const labels = [0,1,2].map(i => candidates[i] ? `Send to ${candidates[i].name}` : 'No additional vendor');
const callbacks = [0,1,2].map(i => candidates[i] ? `vendor:${ticket.id}:${candidates[i].id}` : `vendor:${ticket.id}:none`);
const missing = Array.isArray(ticket.missing_info) ? ticket.missing_info : [];
const canChoose = Boolean(ticket.id && !ticket.human_only && ticket.priority !== 'NEEDS_REVIEW' && missing.length === 0 && ticket.source !== 'fixture' && ticket.source !== 'import');
return [{json:{ticket_id:ticket.id, ticket, airtable:cfg, contacts, candidates, should_send_manager:Boolean(canChoose && (contacts.primary_chat_id || contacts.operator_chat_id)), should_sync:Boolean(cfg.enabled && cfg.base_id), chat_id:contacts.primary_chat_id || contacts.operator_chat_id || '', vendor_1_label:labels[0], vendor_2_label:labels[1], vendor_3_label:labels[2], vendor_1_callback:callbacks[0], vendor_2_callback:callbacks[1], vendor_3_callback:callbacks[2], message_text: canChoose ? [`VENDOR APPROVAL: ${ticket.ref}`, `Priority: ${ticket.priority}`, `Trade: ${ticket.trade || 'UNKNOWN'}`, `Unit: ${ticket.unit_match_display || ticket.unit_identifier || 'not stated'}`, `Issue: ${ticket.issue_summary || ticket.subject || 'Maintenance request'}`, '', 'Select a vendor to send this exact email:', String(ticket.vendor_note || 'No vendor note was drafted.')].join('\n') : `${ticket.ref}: manager review required. No vendor email will be sent automatically.`}}];

parameters.query:
WITH input_values AS (SELECT $1::bigint AS ticket_id, $2::jsonb AS candidates), removed AS (
  DELETE FROM triage.ticket_vendor_candidates WHERE ticket_id = (SELECT ticket_id FROM input_values)
), inserted AS (
  INSERT INTO triage.ticket_vendor_candidates (ticket_id, vendor_id, vendor_name, vendor_email, candidate_rank)
  SELECT i.ticket_id, c->>'id', c->>'name', c->>'email', ord::smallint FROM input_values i, jsonb_array_elements(i.candidates) WITH ORDINALITY AS x(c, ord)
  WHERE c->>'id' IS NOT NULL AND ord <= 3
  ON CONFLICT (ticket_id, vendor_id) DO UPDATE SET vendor_name = EXCLUDED.vendor_name, vendor_email = EXCLUDED.vendor_email, candidate_rank = EXCLUDED.candidate_rank
  RETURNING *
), updated AS (
  UPDATE triage.tickets SET vendor_status = CASE WHEN EXISTS (SELECT 1 FROM inserted) THEN 'AWAITING_VENDOR' ELSE 'NEEDS_VENDOR_ASSIGNMENT' END
  WHERE id = (SELECT ticket_id FROM input_values) RETURNING *
)
SELECT (SELECT ticket_id FROM input_values) AS ticket_id, count(*)::int AS candidate_count FROM inserted;
